    treeNode = treeNode.parent as any;
  }
  mergedPath.treeNodePath.reverse();
  if (!includeSelf) mergedPath.treeNodePath.pop();
  mergedPath.keyPath = mergedPath.treeNodePath.map((treeNode) => treeNode.key);
  return mergedPath as any;
}

